import * as THREE from 'three/webgpu';
import { texture, uv, float, mix, vec3, smoothstep } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh, Color, Vector2 } = ctx.THREE;

  const group = new Group();
  group.name = 'hub-journal-card-1';

  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };
  const ink = new Color(colors.ink);
  const paper = new Color(colors.paper);
  const surface = new Color(colors.surface);

  // Subjects vanish on staged black void — build a backdrop grading the dark-first surface gradient
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new THREE.MeshBasicNodeMaterial();
  const vU = uv();
  const grad = mix(vec3(surface), vec3(ink.clone().lerp(paper, 0.04)), smoothstep(float(0.0), float(1.0), vU.y));
  backdropMat.colorNode = grad;
  backdropMat.transparent = true;
  backdropMat.opacityNode = float(0.92);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // Main textured plane (journal card face)
  const cardGeo = new PlaneGeometry(1, 1);
  const cardMat = new THREE.MeshBasicNodeMaterial();
  cardMat.transparent = false;
  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.position.set(0, 0, 0);
  group.add(cardMesh);

  // load the texture via ctx loader (cached, synchronous caller; .then is fine — it mutates mat)
  const tex = ctx.textureLoader.loadTexture(config.imageUrl);
  tex.then((t) => {
    t.colorSpace = THREE.SRGBColorSpace;
    t.anisotropy = 8;
    cardMat.map = t;
    // tint the image toward ink/paper world so it sits in-stage rather than glued stock
    cardMat.colorNode = mix(texture(t), vec3(new Color('#0e0e14')), float(0.12));
    cardMat.needsUpdate = true;
  });

  // subtle vignette over the card to tie to the dark stage
  const vignetteGeo = new PlaneGeometry(1.02, 1.02);
  const vignetteMat = new THREE.MeshBasicNodeMaterial();
  vignetteMat.transparent = true;
  const vu = uv();
  const d = vu.sub(vec3(0.5, 0.5, 0.0)).length();
  vignetteMat.opacityNode = smoothstep(float(0.35), float(0.72), d).mul(float(0.65));
  vignetteMat.colorNode = vec3(surface);
  const vignette = new Mesh(vignetteGeo, vignetteMat);
  vignette.position.set(0, 0, 0.002);
  group.add(vignette);

  // thin accent rule along the card bottom edge (signal red, <10% of frame)
  const ruleGeo = new PlaneGeometry(1.0, 0.018);
  const ruleMat = new THREE.MeshBasicNodeMaterial();
  ruleMat.colorNode = vec3(new Color(colors.accent));
  const rule = new Mesh(ruleGeo, ruleMat);
  rule.position.set(0, -0.52, 0.004);
  group.add(rule);

  // engineered grain plane above subject to kill flat regions without pastel blur
  const grainGeo = new PlaneGeometry(7, 6);
  const grainMat = new THREE.MeshBasicNodeMaterial();
  grainMat.transparent = true;
  grainMat.opacityNode = float(0.035);
  grainMat.colorNode = mix(vec3(surface), vec3(paper), float(0.5));
  const grain = new Mesh(grainGeo, grainMat);
  grain.position.set(0, 0, -2.49);
  group.add(grain);

  // frame the card with a slim machined-metal edge (lit by backdrop gradient, not flat void)
  const edgeColor = ink.clone().lerp(paper, 0.12);
  const edgeGeoH = new PlaneGeometry(1.02, 0.02);
  const edgeGeoV = new PlaneGeometry(0.02, 1.02);
  const edgeMat = new THREE.MeshBasicNodeMaterial();
  edgeMat.colorNode = vec3(edgeColor);
  const edgeTop = new Mesh(edgeGeoH, edgeMat); edgeTop.position.set(0, 0.52, 0.003); group.add(edgeTop);
  const edgeBot = new Mesh(edgeGeoH, edgeMat); edgeBot.position.set(0, -0.52, 0.003); group.add(edgeBot);
  const edgeLeft = new Mesh(edgeGeoV, edgeMat); edgeLeft.position.set(-0.52, 0, 0.003); group.add(edgeLeft);
  const edgeRight = new Mesh(edgeGeoV, edgeMat); edgeRight.position.set(0.52, 0, 0.003); group.add(edgeRight);

  // cleanup
  group.userData.cleanup = () => {
    backdropGeo.dispose(); backdropMat.dispose();
    cardGeo.dispose(); cardMat.dispose();
    vignetteGeo.dispose(); vignetteMat.dispose();
    ruleGeo.dispose(); ruleMat.dispose();
    grainGeo.dispose(); grainMat.dispose();
    edgeGeoH.dispose(); edgeGeoV.dispose(); edgeMat.dispose();
  };

  group.userData.handlers = {};

  return group;
}
